tafsir_text:
{  فَلَنَسْأَلَنَّ الَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْأَلَنَّ الْمُرْسَلِينَ }

المعنى :

{  فلنسألن الذين أرسل إليهم ولنسألن المرسلين } بعد أن أشار إلى إهلاكهم في الدنيا أشار إلى أنهم يسألون في الآخرة ويسأل المرسلون إليهم ،  ويشهدون عليهم

{  وَالَّذِينَ كَذَّبُواْ بِآيَاتِنَا وَاسْتَكْبَرُواْ عَنْهَا أُوْلََئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ }

المعنى :

{  والذين كذبوا بآياتنا واستكبروا عنها أولئك أصحاب النار هم فيها خالدون } كان أستاذنا رضي الله عنه وأرضاه يقرأ لتلاميذه مقطعا مقطعا من الكتاب المقرر للتدريس ويشرحه لهم بكلام يفهمه كل الناس ،  فإذا كان المقطع واضحا ومفهوما للجميع علق عليه بكلمة :   " توضيح الواضحات من أشكل المشكلات "  .  ومشى إلى غيره .

{  وَقَالَتْ أُولاَهُمْ لأُخْرَاهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍ فَذُوقُواْ الْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ }

المعنى :

{  وقالت أولاهم لأخراهم فما كان لكم علينا من فضل } طلب التابعون أن يزيد في عذاب المتبوعين فقال هؤلاء لأولئك :  ولماذا هذا الطلب ؟  وكلنا في الجزاء سواء ولا تفاوت في شيء حتى يزيد الله في عذابنا دون عذابكم ثم توجه المتبوعون إلى التابعين وقالوا لهم جوابا عن طلب المزيد في عذابهم :  {  فذوقوا العذاب بما كنتم تكسبون } مختارين من الآثام وما كان لنا عليكم من سلطان .

{  قَالَ الَّذِينَ اسْتَكْبَرُواْ إِنَّا بِالَّذِيَ آمَنتُمْ بِهِ كَافِرُونَ }

المعنى :

{  قال الذين استكبروا- للمؤمنين المستضعفين- إنا بالذي آمنتم به كافرون } .  على الرغم من الدلائل والبينات القاطعة على نبوة صالح ،  لأن مصالحهم فوق الأديان السماوية ،  والبراهين العقلية ،  قال الرازي :  هذه الآية من أعظم ما يحتج به على أن الاستكبار إنما يتولد من كثرة المال والجاه ،  لأن هذه الكثرة هي التي حملتهم على التمرد والإباء والكفر .

{  فَأَخَذَتْهُمُ الرَّجْفَةُ فَأَصْبَحُواْ فِي دَارِهِمْ جَاثِمِينَ }

المعنى :

{  فأخذتهم الرجفة فأصبحوا في دارهم جاثمين } هذا هو الجواب الصحيح لمن عاند وتمرد وأبى إلا الضلال والفساد وتقدمت هذه الآية بالحرف 78 من هذه السورة .

{  أَفَأَمِنُواْ مَكْرَ اللّهِ فَلاَ يَأْمَنُ مَكْرَ اللّهِ إِلاَّ الْقَوْمُ الْخَاسِرُونَ }

المعنى :

{  أفأمنوا مكر الله فلا يأمن مكر الله إلا القوم الخاسرون } المراد بمكر الله هنا العذاب الذي يأتيهم بغتة دون سابق إنذار وسبق الكلام عن مكر الله تعالى في تفسير الآية 54 من آل عمران ج 2 ص 68 وأنه سبحانه يصف نفسه بالماكر لأنه يبطل مكر الماكرين وبالشاكر لأنه يثيب الشاكرين وبالتواب لأنه يقبل من التائبين .  .  أما أنهم الخاسرون فلأنهم أوقعوا أنفسهم في الخسران بسبب عنادهم واستهتارهم .

{  قَالَ الْمَلأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَذَا لَسَاحِرٌ عَلِيمٌ }

المعنى :

/م109

{  وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَونَ يَسُومُونَكُمْ سُوَءَ الْعَذَابِ يُقَتِّلُونَ أَبْنَاءكُمْ وَيَسْتَحْيُونَ نِسَاءكُمْ وَفِي ذَلِكُم بَلاء مِّن رَّبِّكُمْ عَظِيمٌ }

المعنى :

{  وإذ أنجيناكم من آل فرعون يسومونكم سوء العذاب يقتلون أبناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم } تقدم نظيره في الآية 49 من سورة البقرة ج 1 ص 99 .

{  قَالَ يَا مُوسَى إِنِّي اصْطَفَيْتُكَ عَلَى النَّاسِ بِرِسَالاَتِي وَبِكَلاَمِي فَخُذْ مَا آتَيْتُكَ وَكُن مِّنَ الشَّاكِرِينَ }

المعنى :

{  قال يا موسى إني اصطفيتك على الناس برسالاتي وبكلامي فخذ ما آتيتك وكن من الشاكرين } .  بعد أن تضرع موسى ( ع ) إلى خالقه ذكره الله بنعمه وأعظمها النبوة والتكلم والمراد بالناس ناس زمانه بدليل قوله :  {  برسالاتي } فإن الله قد اختار رسلا كثيرين قبل موسى وبعده أما تخصيصه بالتكليم فلا دلالة فيه على الأفضلية وإن دل على الفضل فإن إرسال الروح الأمين إلى خاتم الرسل وسيد النبيين هو أعلى المراتب وأفضلها على الإطلاق .

{  وَالَّذِينَ كَذَّبُواْ بِآيَاتِنَا وَلِقَاء الآخِرَةِ حَبِطَتْ أَعْمَالُهُمْ هَلْ يُجْزَوْنَ إِلاَّ مَا كَانُواْ يَعْمَلُونَ }

المعنى :

{  والذين كذبوا بآياتنا ولقاء الآخرة حبطت أعمالهم هل يجزون إلا ما كانوا يعملون } كل من لا يؤمن بالله ولقاء ربه فهو من الهالكين إذا ويذهب ما كان يفاخر به ويكاثر سدى وهباء جزاء على كفره وعناده .  .  وأعجبني ما قاله هنا بعض المفسرين غفر الله له وشمله برحمته ولذا أنقله بالحرف قال :   " حبوط الأعمال مأخوذ من قولهم :  حبطت الناقة إذا رعت نباتا ساما .  فانتفخ بطنها ثم نفقت ،  وهو وصف ملحوظ في طبيعة الباطل يصدر من المكذبين بآيات الله ولقاء الآخرة فالمكذب ينتفخ حتى يظنه الناس من عظمة وقوة ،  ثم ينفق كما تنفق الناقة التي رعت ذلك النبات السام "  .

{  قَالَ رَبِّ اغْفِرْ لِي وَلأَخِي وَأَدْخِلْنَا فِي رَحْمَتِكَ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ }

المعنى :

وهنا يلين موسى ( ع ) وتأخذه عاطفة الرحمة والأخوة {  قال رب اغفر لي ولأخي وأدخلنا في رحمتك وأنت أرحم الراحمين } استغفر لنفسه لما كان من قسوته مع أخيه واستغفر لأخيه مخافة تقصيره في هدايتهم وردعهم عن الشرك والارتداد .  .  وليس من شك أن الله قد استجاب لدعوة موسى ( ع ) لأنه أرحم الراحمين .  ولعلمه بإخلاص موسى وهرون .

{  أَوْ تَقُولُواْ إِنَّمَا أَشْرَكَ آبَاؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةً مِّن بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ الْمُبْطِلُونَ }

المعنى :

{  أو تقولوا إنما أشرك آباؤنا من قبل وكنا ذرية من بعدهم أفتهلكنا بما فعل المبطلون } .  يقلد الإنسان في الأشياء التي تحتاج إلى التخصص وتستغرق سنوات من الدراسة كالطب والهندسة وما إليهما أما الإدراكات الفطرية التي لا تكلف الإنسان أكثر من اليقظة والتنبه كوجود الله ووحدانيته أما هذه فالكل فيها سواء .  .  وقد أقام الله سبحانه البراهين الوافية الكافية على وحدانيته ومنح كل عاقل الاستعداد لتفهمها بيسر ولم يبق عذرا لمعتذر بأنه جحد أو أشرك تقليدا لغيره من المبطلين .  .  ولا فرق أبدا في نظر العقل بين من يعمل بغير  علمه متعمدا وبين من يتبع الباطل جهلا به ومن غير قصد مع قدرته على معرفته وتمييزه عن غيره .

{  وَكَذَلِكَ نُفَصِّلُ الآيَاتِ وَلَعَلَّهُمْ يَرْجِعُونَ }

المعنى :

{  وكذلك نفصل الآيات ولعلهم يرجعون } إلى عقولهم التي تؤدي بهم حتما بمعونة الدلائل إلى عقيدة التوحيد .  أنظر تفسير الآية 41 من سورة الأنعام فقرة  " الله والفطرة "  ص 188 .

{  وَلاَ يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلاَ أَنفُسَهُمْ يَنصُرُونَ }

المعنى :

{  ولا يستطيعون لهم نصرا ولا أنفسهم ينصرون } إن النصر والغلبة والإعزاز والإذلال بيد الله والأصنام أحجار تبول عليها القطط والكلاب فلا تنصر ولا تنتصر

{  وَإِن تَدْعُوهُمْ إِلَى الْهُدَى لاَ يَتَّبِعُوكُمْ سَوَاء عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَامِتُونَ }

المعنى :

{  وإن تدعوهم إلى الهدى لا يتبعوكم سواء عليكم أدعوتموهم أم أنتم صامتون } هذه الأصنام لا تخلق ولا تنصر ولا تنتصر ولا تهدي ولا تهتدي ولا تدعو أحدا ولا تستجيب لدعوة أحد ومع كل هذا تعبد .

{  إِنَّ الَّذِينَ تَدْعُونَ مِن دُونِ اللّهِ عِبَادٌ أَمْثَالُكُمْ فَادْعُوهُمْ فَلْيَسْتَجِيبُواْ لَكُمْ إِن كُنتُمْ صَادِقِينَ }

المعنى :

{  إن الذين تدعون من دون الله عباد أمثالكم فادعوهم فليستجيبوا لكم إن كنتم صادقين } .  لقد زعمتم أيها المشركون أن الأصنام آلهة والإله ينفع ويضر ويعطي ويمنع فاطلبوا منهم لنرى هل يستجيبون لطلبكم ؟

{  إِنَّ وَلِيِّيَ اللّهُ الَّذِي نَزَّلَ الْكِتَابَ وَهُوَ يَتَوَلَّى الصَّالِحِينَ }

المعنى :

{  إن ولي الله الذي نزل الكتاب وهو يتولى الصالحين } بعد أن تحدى النبي صلى الله عليه وسلم المشركين وآلهتهم قال لهم :  أنتم تتولون هذه الأصنام وأنا أتولى الله الذي نزل علي القرآن وفيه تبيان كل شيء وهو أيضا يتولى حفظي وحراستي فهل لأصنامكم كتاب ؟  وهل تتولى هي حفظكم وحراستكم ؟  وكانت النتيجة كما يعرفها الجميع إذلال الشرك والمشركين وإعزاز الإسلام والمسلمين .

{  وَالَّذِينَ تَدْعُونَ مِن دُونِهِ لاَ يَسْتَطِيعُونَ نَصْرَكُمْ وَلا أَنفُسَهُمْ يَنْصُرُونَ }

المعنى :

{  والذين تدعون من دونه لا يستطيعون نصركم ولا أنفسهم ينصرون } تقدم هذا في الآية 192 وجاء التكرار لأن النبي صلى الله عليه وسلم تحدى الأصنام أن تناله بأذى فناسب أن يشير إلى أنها أعجز من أن تنصر أو تنتصر .

{  وَإِخْوَانُهُمْ يَمُدُّونَهُمْ فِي الْغَيِّ ثُمَّ لاَ يُقْصِرُونَ }

المعنى :

{  وإخوانهم يمدونهم في الغي ثم لا يقصرون } .  المراد بالإخوان هنا الشياطين والضمير في إخوانهم يعود إلى المشركين الذين تقدم ذكرهم والضمير المرفوع في يمدونهم يعود إلى الشياطين والضمير المنصوب يعود إلى المشركين والمراد بلا يقصرون لا يكف الشياطين عن إمداد المشركين بالإغواء والإفساد وملخص المعنى أن الشياطين هم إخوان المشركين لا يكفون عن غوايتهم وتضليلهم .
